"import pytest\n\n\ndef test_flip_case_empty():\n    assert flip_case('') == ''\n\n\ndef test_flip_case_all_lower():\n    s = 'abcdefghijklmnopqrstuvwxyz'\n    assert flip_case(s) == s.swapcase()\n\n\ndef test_flip_case_all_upper():\n    s = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'\n    assert flip_case(s) == s.swapcase()\n\n\ndef test_flip_case_mixed():\n    s = 'Hello World! 123'\n    assert flip_case(s) == s.swapcase()\n\n\ndef test_flip_case_unicode():\n    s = 'Ã±ÃÃ§ÃÃ¡Ã'\n    assert flip_case(s) == s.swapcase()\n\n\ndef test_flip_case_non_string_raises():\n    with pytest.raises(AttributeError):\n        flip_case(123)\n\n\ndef test_flip_case_length_unchanged():\n    s = 'TestString123'\n    res = flip_case(s)\n    assert len(res) == len(s)"

